  var records = Object.freeze(payload.records);
  var aliases = Object.freeze(payload.aliases);
  function clean(value) { return String(value == null ? '' : value).trim(); }
  function keyOf(location) {
    if (typeof location === 'string') return location.split('|').map(clean).join('|');
    location = location || {};
    return [location.province, location.city, location.district].map(clean).join('|');
  }
  function result(row, level, matchedKey, estimated) {
    return { longitude: row.longitude, level: level, source: row.source, sourceVersion: payload.VERSION, matchedKey: matchedKey, estimated: estimated };
  }
  function resolveLocation(location, options) {
    options = options || {};
    var key = keyOf(location);
    var row = records[key];
    if (row) return result(row, 'county', key, false);
    var aliasKey = aliases[key];
    if (aliasKey && records[aliasKey]) return result(records[aliasKey], 'county_alias', aliasKey, false);
    var parts = key.split('|');
    if (options.allowFallback === false) throw new Error('县级经度未匹配: ' + key);
    var candidates = Object.keys(records).filter(function (candidate) {
      var c = candidate.split('|');
      return parts[0] && c[0] === parts[0] && parts[1] && c[1] === parts[1];
    });
    if (candidates.length) {
      var cityLongitude = candidates.reduce(function (sum, candidate) { return sum + records[candidate].longitude; }, 0) / candidates.length;
      return result({ longitude: Number(cityLongitude.toFixed(6)), source: 'estimated-city', }, 'city_fallback', parts.slice(0, 2).join('|'), true);
    }
    candidates = Object.keys(records).filter(function (candidate) { return parts[0] && candidate.indexOf(parts[0] + '|') === 0; });
    if (candidates.length) {
      var provinceLongitude = candidates.reduce(function (sum, candidate) { return sum + records[candidate].longitude; }, 0) / candidates.length;
      return result({ longitude: Number(provinceLongitude.toFixed(6)), source: 'estimated-province' }, 'province_fallback', parts[0], true);
    }
    return result({ longitude: 120, source: 'default-fallback' }, 'default_fallback', '', true);
  }
  return { VERSION: payload.VERSION, records: records, aliases: aliases, resolveLocation: resolveLocation };
